import { describe, test, expect, vi, beforeEach } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useCartMessages } from './useCartMessages';

// Hoisted so the vi.mock factory below (hoisted above these imports by Vitest) can reference it —
// a plain `const` here would not yet be initialised at that point (same pattern as
// useCartMergeAndCap.test.ts / useWishlistAuthDrawer.test.tsx).
const { mockToast } = vi.hoisted(() => ({
  mockToast: vi.fn(),
}));

// Real use-toast.js ships JSX in a .js-extension file that Vitest's default transform can't parse
// when pulled in transitively — same known gap use-toast.js has everywhere else it's imported in
// this codebase's own tests (see recommended-products/index.test.tsx, product-view/index.test.tsx
// and recentlyViewed/index.test.tsx's identical mocks). Unlike those call sites, this file's whole
// subject is what gets sent to the returned toast function, so the mock is a controllable
// `vi.fn()` rather than a bare no-op stub — this is the file under test's one external dependency.
vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
  useToast: () => mockToast,
}));

describe('useCartMessages', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('notifyAddedToWishlist — SFCC-272 AC5', () => {
    test('emits the product-named copy verbatim, with the real product name substituted', () => {
      const { result } = renderHook(() => useCartMessages());

      result.current.notifyAddedToWishlist('Cloud 91 Small Clutch');

      expect(mockToast).toHaveBeenCalledTimes(1);
      expect(mockToast).toHaveBeenCalledWith({
        title: 'Cloud 91 Small Clutch added to Wishlist',
        status: 'success',
      });
    });

    test('interpolates a second, different product name — proves this is a template, not the fixture string hardcoded for every call', () => {
      const { result } = renderHook(() => useCartMessages());

      result.current.notifyAddedToWishlist('Harlow Midi Dress');

      expect(mockToast).toHaveBeenCalledWith({
        title: 'Harlow Midi Dress added to Wishlist',
        status: 'success',
      });
    });
  });

  describe('notifyAlreadyInWishlist — SFCC-272 AC6', () => {
    test('emits the exact Figma copy verbatim, warning status, no interpolation', () => {
      const { result } = renderHook(() => useCartMessages());

      result.current.notifyAlreadyInWishlist();

      expect(mockToast).toHaveBeenCalledTimes(1);
      expect(mockToast).toHaveBeenCalledWith({
        title: 'An item in your bag already exists in Wishlist',
        status: 'warning',
      });
    });
  });

  describe('notifyMaxQuantityReached — CAI-017 / SFCC-250', () => {
    test('emits the exact Figma copy verbatim with warning status, not error', () => {
      const { result } = renderHook(() => useCartMessages());

      result.current.notifyMaxQuantityReached();

      expect(mockToast).toHaveBeenCalledTimes(1);
      expect(mockToast).toHaveBeenCalledWith({
        title: 'An item in your bag has reached maximum quantity',
        status: 'warning',
      });
    });

    // CAI-017's own requirement text says "an error message will be displayed" — this build's own
    // gate (findings.md #4) resolved that against the Figma warning-variant rendering and SFCC-250
    // AC4's non-blocking behaviour. Asserted as its own negative case, not just implied by the
    // positive assertion above, since a status typo (e.g. 'error' instead of 'warning') would
    // otherwise be the one-character mistake most likely to slip past review here.
    test('never uses the error status for the max-quantity message', () => {
      const { result } = renderHook(() => useCartMessages());

      result.current.notifyMaxQuantityReached();

      expect(mockToast).not.toHaveBeenCalledWith(expect.objectContaining({ status: 'error' }));
    });
  });

  describe('one shared emit path (SFCC-404 marker)', () => {
    test('every message reaches the same underlying toast function — no second, bypassing call site', () => {
      const { result } = renderHook(() => useCartMessages());

      result.current.notifyAddedToWishlist('Cloud 91 Small Clutch');
      result.current.notifyAlreadyInWishlist();
      result.current.notifyMaxQuantityReached();

      expect(mockToast).toHaveBeenCalledTimes(3);
    });
  });
});

